const ICO_TXT = { panier: 'panier', filet: 'filet', canne: 'canne', coffre: 'coffre', 'a-tresor': 'Ouvrir', 'a-parler': 'Parler', 'a-prendre': 'Prendre', 'a-cueillir': 'Cueillir', 'a-donner': 'Donner', 'a-attraper': 'Attraper', 'a-pecher': 'Pêcher' };
/* ----- pas d'emojis dans les textes : les objets à récolter sont remplacés par leur miniature, le reste est retiré ----- */
const MINI_B64 = {"coconut": "", "mango": "", "banana": "", "butterfly": "", "flower": "", "fish": "", "crab": "", "shell": ""};
const MINI_OF = { '\u{1F34C}': 'banana', '\u{1F338}': 'flower', '\u{1F33A}': 'flower', '\u{1F98B}': 'butterfly', '\u{1F41F}': 'fish', '\u{1F965}': 'coconut', '\u{1F96D}': 'mango', '\u{1F41A}': 'shell', '\u{1F980}': 'crab' };
const MINI_IMG = {};
(() => { const st = document.createElement('style'); st.textContent = '.emi{display:inline-block;width:1.35em;height:1.35em;vertical-align:-.32em;margin:0 1px;background:center/contain no-repeat}' + Object.keys(MINI_B64).map(k => '.e-' + k + '{background-image:url(data:image/png;base64,' + MINI_B64[k] + ')}').join(''); document.head.appendChild(st); Object.keys(MINI_B64).forEach(k => { const i = new Image(); i.src = 'data:image/png;base64,' + MINI_B64[k]; MINI_IMG[k] = i; }); })();
const EMO_C = '[\u{1F000}-\u{1FFFF}☀-☄☆-⛿✨⭐⬆✅❌-❎❗⏩-⏺️‍]';
const EMO_RX = new RegExp(EMO_C, 'gu'), EMO_SENT = new RegExp('([^\\s.!?…:»,;\uE001' + EMO_C.slice(1, -1) + '])[ ]*(?:' + EMO_C + ')+[ ]*(?=[A-ZÀ-Ý«])', 'gu');
function emoText(s, html, trim) {   // html = true : les objets à récolter deviennent une miniature ; sinon tout est retiré
  s = String(s); const keep = [];
  if (html) s = s.replace(/[\u{1F300}-\u{1FAFF}]️?/gu, m => { const k = MINI_OF[m.replace('️', '')]; if (!k) return m; keep.push(k); return '' + (keep.length - 1) + ''; });
  { const t0 = s; s = s.replace(EMO_SENT, '$1. ').replace(EMO_RX, '').replace(/ {2,}/g, ' '); if (s !== t0) s = s.replace(/ +([.,;])/g, '$1'); }
  if (trim) s = s.trim();
  return s.replace(/(\d+)/g, (m, i) => '<i class="emi e-' + keep[+i] + '"></i>');
}
const emoFix = html => String(html).split(/(<[^>]*>)/).map((p, i) => i % 2 ? p : emoText(p, true, false)).join('');

/* ----- barre de défilement toujours visible (téléphone / tablette) : sur iPhone la barre native disparaît ----- */
(() => {
  const SEL = ['#paint', '#wardrobe .card', '#memory', '#puzzle', '#rythme', '#settings .card', '#levelPick .card', '#tips'];
  const mq = matchMedia('(pointer:coarse), (max-width:700px)');
  const make = (el, inset) => {
    const bar = document.createElement('div'); bar.className = 'vsb'; const th = document.createElement('i'); bar.appendChild(th); document.body.appendChild(bar);
    let drag = null;
    const upd = () => {
      const r = el.getBoundingClientRect(), sh = el.scrollHeight, ch = el.clientHeight;
      if (!mq.matches || !r.height || sh <= ch + 6 || getComputedStyle(el).visibility === 'hidden') { bar.style.display = 'none'; return; }
      const tr = Math.max(40, r.height - 24 - inset), thH = Math.max(40, tr * ch / sh), max = sh - ch, top = max > 0 ? el.scrollTop / max * (tr - thH) : 0;
      bar.style.display = 'block'; bar.style.left = (r.right - 16) + 'px'; bar.style.top = (r.top + 12 + inset) + 'px'; bar.style.height = tr + 'px'; th.style.height = thH + 'px'; th.style.transform = 'translateY(' + top + 'px)'; bar._k = { tr, thH, max };
    };
    const setFrom = y => { const k = bar._k; if (!k) return; const r = bar.getBoundingClientRect(), t = Math.max(0, Math.min(k.tr - k.thH, y - r.top - k.thH / 2)); el.scrollTop = t / (k.tr - k.thH) * k.max; upd(); };
    bar.addEventListener('pointerdown', e => { e.preventDefault(); e.stopPropagation(); drag = e.pointerId; bar.setPointerCapture(e.pointerId); setFrom(e.clientY); });
    bar.addEventListener('pointermove', e => { if (drag === e.pointerId) { e.preventDefault(); setFrom(e.clientY); } });
    const end = e => { if (drag === e.pointerId) drag = null; }; bar.addEventListener('pointerup', end); bar.addEventListener('pointercancel', end);
    el.addEventListener('scroll', upd, { passive: true }); addEventListener('resize', upd); setInterval(upd, 350); upd();
  };
  const go = () => { /* barre invisible : on fait simplement glisser le doigt de haut en bas */ SEL.forEach(s => { const el = document.querySelector(s); if (el) { el.style.overflowY = el.style.overflowY || 'auto'; el.style.webkitOverflowScrolling = 'touch'; el.style.overscrollBehavior = 'contain'; } }); };
  if (document.readyState === 'loading') addEventListener('DOMContentLoaded', go); else go();
})();

(() => {   // même les petits libellés de l'interface (boutons, menus) n'ont plus d'emojis : seuls les boutons « icône seule » les gardent
  const hasEmo = new RegExp(EMO_C, 'u'), onlyEmo = new RegExp('^(?:' + EMO_C + '|\\s)+$', 'u');
  const clean = n => { if (n.nodeType === 3) { const v = n.nodeValue; if (v && hasEmo.test(v) && !onlyEmo.test(v)) { const w = emoText(v, false, false); if (w !== v) n.nodeValue = w; } } else if (n.nodeType === 1 && n.tagName !== 'SCRIPT' && n.tagName !== 'STYLE') n.childNodes.forEach(clean); };
  const go = () => { clean(document.body); new MutationObserver(ms => ms.forEach(m => { if (m.type === 'characterData') clean(m.target); else m.addedNodes.forEach(clean); })).observe(document.body, { childList: true, subtree: true, characterData: true }); };
  if (document.body) go(); else addEventListener('DOMContentLoaded', go);
})();
