  const k = Math.min(1, dt * .8); L.s += (T.s - L.s) * k; L.m += (T.m - L.m) * k; if (Math.abs(T.s - L.s) < .01) L.s = T.s; if (Math.abs(T.m - L.m) < .01) L.m = T.m; L.murk = Math.max(L.s, L.m);
