addEventListener('pointerup', e => { const p = tapPend; if (!p || p.id !== e.pointerId) return; tapPend = null; if (Math.hypot(e.clientX - p.x, e.clientY - p.y) < 16 && performance.now() - p.t < 700) p.fn(); }, true);
