function backupCode() { const o = { v: 1, slots: {}, looks: null }; try { for (let n = 1; n <= NSLOTS; n++) { const s = localStorage.getItem(slotKey(n)); if (s) o.slots[n] = s; } o.looks = localStorage.getItem(WD_SAVE_KEY); } catch (e) {} return btoa(unescape(encodeURIComponent(JSON.stringify(o)))); }
press($('#setCopy'), () => { const c = backupCode(), ok = () => { $('#setMsg').textContent = '📋 Code copié ! Garde-le dans une note : il te permet de retrouver tes parties.'; }; try { navigator.clipboard.writeText(c).then(ok, () => { prompt('Copie ce code de secours :', c); }); } catch (e) { prompt('Copie ce code de secours :', c); } });
function restoreCode(c) { try { const o = JSON.parse(decodeURIComponent(escape(atob(c.trim())))); let n = 0; for (const k in o.slots) { const f = +k; if (f >= 1 && f <= NSLOTS && !localStorage.getItem(slotKey(f))) { localStorage.setItem(slotKey(f), o.slots[k]); idbPut(slotKey(f), o.slots[k]); n++; } } if (o.looks && !localStorage.getItem(WD_SAVE_KEY)) localStorage.setItem(WD_SAVE_KEY, o.looks); refreshTitle(); $('#setMsg').textContent = n ? '✔ ' + n + ' partie(s) retrouvée(s) : elles sont sur l\'écran titre.' : 'Rien de nouveau à récupérer (les emplacements sont déjà pris).'; } catch (e) { $('#setMsg').textContent = '❌ Ce code n\'est pas valide.'; } }
press($('#setPaste'), () => { const c = prompt('Colle ici ton code de secours :'); if (c) restoreCode(c); });
press($('#setFile'), () => { try { const c = backupCode(), a = document.createElement('a'); a.href = URL.createObjectURL(new Blob([c], { type: 'text/plain' })); a.download = 'swaalia-sauvegarde.txt'; document.body.appendChild(a); a.click(); setTimeout(() => { a.remove(); URL.revokeObjectURL(a.href); }, 500); $('#setMsg').textContent = 'Fichier de sauvegarde créé : garde-le précieusement (Fichiers, mail, etc.).'; } catch (e) { $('#setMsg').textContent = 'Impossible de créer le fichier : utilise plutôt le code de secours.'; } });
