    if (j.k === 'fly') { const a = .55 + .45 * Math.sin(t * 3 + i * 2.1), gr = g.createRadialGradient(cx, cy, 0, cx, cy, jw * .26); gr.addColorStop(0, 'rgba(255,248,140,' + (.9 * a) + ')'); gr.addColorStop(.35, 'rgba(230,255,120,' + (.45 * a) + ')'); gr.addColorStop(1, 'rgba(230,255,120,0)'); g.fillStyle = gr; g.beginPath(); g.arc(cx, cy, jw * .26, 0, 7); g.fill(); g.fillStyle = 'rgba(255,255,230,' + a + ')'; g.beginPath(); g.arc(cx, cy, Math.max(1, jw * .04), 0, 7); g.fill(); }
