const R_PICK = 30, R_NPC = 42, R_CHEST = 36, R_SWAN = 86;

function perchVisible() { return level === 'balade' || phase === 'appeared' || phase === 'returned' || (phase === 'reveal' && cine && cine.t > .8); }
const swanLake = () => (phase === 'returned' || level === 'balade') && !cine;
