    const D = DIFF[level]; fs.phase = 'fight';
    fs.fight = { T: .1, mode: 'rest', mt: 1.1, prog: D.start, t: 0, lost: 0, inZ: false }; sfx.bite(); return;   // tension de la ligne : on tient quand le poisson est fatigué, on relâche quand il tire
