      f.x = f.bx + Math.sin(time * .65 + f.ph) * 13;
      f.y = f.by + Math.sin(time * 1.8 + f.ph) * 2.5;
      f.dir = Math.cos(time * .65 + f.ph) >= 0 ? 1 : -1;
