  if (SC === SC_HOME && dist(IN.x, IN.y, COOK_SPOT[0], COOK_SPOT[1]) < 120) L.push({ id: 'cook', x: COOK_HL[0], y: COOK_HL[1], go: () => { actQueued = false; openCook(); } });
