  const cvs = CK.box.querySelector('#ckC2'), c2 = cvs.getContext('2d'), base = new Image(), imgs = {}, CPOLY = raw ? CAKE_POLY.r : CAKE_POLY.g; let cakePath = null;
  DECO.forEach(d => { const i = new Image(); i.src = 'assets/cook/dc/d' + String(d[1]).padStart(2, '0') + '.png'; i.onload = draw; imgs[d[1]] = i; });
